# Surah Yunus (chapter 10) — part 7: ayat 61-70 (IDs 1425-1434)
SURAH = 10

ENTRIES = {
1425: (
"اور — تم — جس — حالت میں ہو — اور — اس — میں سے — تم — جو — تلاوت کرتے ہو — اور — میں — تم عمل کرتے ہو — مگر — ہم — تمہارے — پر گواہ ہوتے ہیں — جب — تم — اس — میں مشغول ہو — اور — تمہارے رب — سے — ذرہ — کے برابر — بھی — کوئی چیز — زمین میں — یا — آسمان میں — نہیں چھپی — اور — نہ — اس سے چھوٹی — نہ بڑی — مگر — ایک — واضح کتاب میں ہے",
"""۱۔ اللہ — ہر چیز کو — دیکھتا ہے — ذرہ بھی — اوجھل نہیں۔
۲۔ ’’وَمَا تَكُونُ فِي شَأْنٍ وَمَا تَتْلُو مِنْهُ مِن قُرْآنٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّۃٍ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَلَا أَصْغَرَ مِن ذَٰلِكَ وَلَا أَكْبَرَ إِلَّا فِي كِتَابٍ مُّبِينٍ‘‘ — اور — تم — جس — حالت میں ہو — اور — اس — میں سے — تم — جو — تلاوت کرتے ہو — اور — میں — تم عمل کرتے ہو — مگر — ہم — تمہارے — پر گواہ ہوتے ہیں — جب — تم — اس — میں مشغول ہو — اور — تمہارے رب — سے — ذرہ — کے برابر — بھی — کوئی چیز — زمین میں — یا — آسمان میں — نہیں چھپی — اور — نہ — اس سے چھوٹی — نہ بڑی — مگر — ایک — واضح کتاب میں ہے — یعنی اللہ — ہر لمحہ — آپ کے ساتھ — گواہ ہے — ذرہ — بھی — لکھا جاتا ہے۔
۳۔ عملی سبق: اللہ — ہر کام میں — گواہ ہے؛ خالص نیت — رکھو۔"""
),
1426: (
"سنو — اللہ کے اولیاء — پر — نہ کوئی خوف ہے — نہ — وہ — غمگین — ہوں گے",
"""۱۔ اللہ — کے اولیاء — کو نہ — خوف — نہ غم۔
۲۔ ’’أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ‘‘ — سنو — اللہ کے اولیاء — پر — نہ کوئی خوف ہے — نہ — وہ — غمگین — ہوں گے — یعنی اللہ کے اولیاء — پر — نہ خوف — ہے نہ غم۔
۳۔ عملی سبق: اللہ کے دوست — خوف اور غم سے آزاد ہیں۔"""
),
1427: (
"وہ — جنہوں نے — ایمان لایا — اور — تقویٰ — اختیار کرتے تھے",
"""۱۔ اولیاءِ اللہ — مؤمن اور متقی — ہیں۔
۲۔ ’’الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ‘‘ — وہ — جنہوں نے — ایمان لایا — اور — تقویٰ — اختیار کرتے تھے — یعنی اللہ کے اولیاء — ایمان والے — اور متقی — ہیں۔
۳۔ عملی سبق: ایمان اور تقویٰ — اللہ کی ولیٰ بننے کی — شرط ہے۔"""
),
1428: (
"ان کے لیے — خوشخبری — ہے دنیا کی زندگی اور آخرت میں — اللہ — کے کلمات — میں کوئی تبدیلی نہیں — یہی — عظیم کامیابی — ہے",
"""۱۔ مؤمنو — دنیا اور آخرت — دونوں میں خوشخبری۔
۲۔ ’’لَهُمُ الْبُشْرَىٰ فِي الْحَيَاۃِ الدُّنْيَا وَفِي الْآخِرَۃِ لَا تَبْدِيلَ لِكَلِمَاتِ اللَّهِ ذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ‘‘ — ان کے لیے — خوشخبری — ہے دنیا کی زندگی اور آخرت میں — اللہ — کے کلمات — میں کوئی تبدیلی نہیں — یہی — عظیم کامیابی — ہے — یعنی مؤمنوں کے لیے — دنیا اور آخرت — دونوں میں خوشخبری ہے — اللہ کے کلمات بدلتے نہیں؛ یہی عظیم کامیابی ہے۔
۳۔ عملی سبق: اللہ کی خوشخبری — دونوں جہانوں — میں — ملتی ہے۔"""
),
1429: (
"اور — ان — کی — بات — آپؐ کو غمگین نہ کرے — بے شک — عزت — سب — اللہ — کی ہے — وہ — سننے والا جاننے والا — ہے",
"""۱۔ کفار کی بات — آپؐ کو غمگین نہ کرے — عزت اللہ — کی ہے۔
۲۔ ’’وَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّ الْعِزَّۃَ لِلَّهِ جَمِيعًا هُوَ السَّمِيعُ الْعَلِيمُ‘‘ — اور — ان — کی — بات — آپؐ کو غمگین نہ کرے — بے شک — عزت — سب — اللہ — کی ہے — وہ — سننے والا جاننے والا — ہے — یعنی کفار کی بات پر — غمگین — نہ ہوں — عزت — سب اللہ کی ہے؛ وہ سنتا اور جانتا ہے۔
۳۔ عملی سبق: عزت — صرف اللہ — سے ملتی ہے۔"""
),
1430: (
"سنو — آسمانوں اور زمین — میں — جو کچھ ہے — وہ — اللہ کا ہے — اور — وہ لوگ جو — اللہ کے سوا — جنہیں — پکارتے ہیں — وہ — شریکوں کی — پیروی نہیں کرتے — وہ — صرف گمان — کی پیروی کرتے ہیں — اور — وہ — اندازہ لگانے والے — ہیں",
"""۱۔ آسمان و زمین کا مالک — اللہ ہے؛ مشرکین محض — گمان — کی پیروی کرتے ہیں۔
۲۔ ’’أَلَا إِنَّ لِلَّهِ مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ وَمَا يَتَّبِعُ الَّذِينَ يَدْعُونَ مِن دُونِ اللَّهِ شُرَكَاءَ إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِن هُمْ إِلَّا يَخْرُصُونَ‘‘ — سنو — آسمانوں اور زمین — میں — جو کچھ ہے — وہ — اللہ کا ہے — اور — وہ لوگ جو — اللہ کے سوا — جنہیں — پکارتے ہیں — وہ — شریکوں کی — پیروی نہیں کرتے — وہ — صرف گمان — کی پیروی کرتے ہیں — اور — وہ — اندازہ لگانے والے — ہیں — یعنی آسمان و زمین میں سب کچھ اللہ کا ہے؛ مشرکین — گمان — اور اندازے — کی پیروی کرتے ہیں۔
۳۔ عملی سبق: یقین — پر عمل کرو؛ گمان — ناکافی ہے۔"""
),
1431: (
"وہ — وہی — ہے — جس نے — رات — کو — آپ کے لیے بنایا — تاکہ — تم — اس میں سکون پاؤ — اور — دن — کو — روشن — بے شک — اس — میں — سننے والوں کے لیے — نشانیاں ہیں",
"""۱۔ رات — سکون — دن — روشنی؛ دونوں — اللہ کی نشانیاں۔
۲۔ ’’هُوَ الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يَسْمَعُونَ‘‘ — وہ — وہی — ہے — جس نے — رات — کو — آپ کے لیے بنایا — تاکہ — تم — اس میں سکون پاؤ — اور — دن — کو — روشن — بے شک — اس — میں — سننے والوں کے لیے — نشانیاں ہیں — یعنی رات — سکون کے لیے ہے؛ دن — روشنی کے لیے؛ اس میں — سننے والوں کے لیے — نشانیاں ہیں۔
۳۔ عملی سبق: رات سکون — دن روشنی — دونوں — اللہ کی نعمتیں ہیں۔"""
),
1432: (
"وہ — کہتے ہیں — اللہ — نے — بیٹا بنایا — وہ پاک ہے — وہ — بے نیاز ہے — جو — کچھ — آسمانوں اور زمین — میں ہے — اس کا ہے — تمہارے — پاس — اس — کا کوئی ثبوت نہیں — کیا — تم — اللہ — پر وہ بات کہتے ہو — جس کا — تمہیں علم نہیں",
"""۱۔ اللہ — کا بیٹا بنانا — سب سے — بڑی بے وقوفی اور تہمت۔
۲۔ ’’قَالُوا اتَّخَذَ اللَّهُ وَلَدًا سُبْحَانَهُ هُوَ الْغَنِيُّ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ إِنْ عِندَكُم مِّن سُلْطَانٍ بِهَٰذَا أَتَقُولُونَ عَلَى اللَّهِ مَا لَا تَعْلَمُونَ‘‘ — وہ — کہتے ہیں — اللہ — نے — بیٹا بنایا — وہ پاک ہے — وہ — بے نیاز ہے — جو — کچھ — آسمانوں اور زمین — میں ہے — اس کا ہے — تمہارے — پاس — اس — کا کوئی ثبوت نہیں — کیا — تم — اللہ — پر وہ بات کہتے ہو — جس کا — تمہیں علم نہیں — یعنی اللہ — کا بیٹا بنانا — تہمت ہے؛ وہ — بے نیاز ہے؛ آسمان و زمین اس کا ہے؛ تمہارے پاس کوئی ثبوت نہیں — کیا — تم بے علمی میں — اللہ پر جھوٹ بولتے ہو۔
۳۔ عملی سبق: اللہ — بے نیاز ہے؛ کسی کو بیٹا — بنانا — بے بنیاد افترا ہے۔"""
),
1433: (
"کہدو — بے شک — وہ لوگ جو — اللہ — پر جھوٹ گھڑتے ہیں — وہ — کامیاب نہیں ہوتے",
"""۱۔ اللہ پر جھوٹ گھڑنا — کامیابی سے محرومی۔
۲۔ ’’قُلْ إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ‘‘ — کہدو — بے شک — وہ لوگ جو — اللہ — پر جھوٹ گھڑتے ہیں — وہ — کامیاب نہیں ہوتے — یعنی اللہ پر جھوٹ گھڑنے والے — کبھی — کامیاب — نہیں ہوتے۔
۳۔ عملی سبق: اللہ پر جھوٹ — کبھی — کامیاب — نہیں ہوتا۔"""
),
1434: (
"دنیا میں — تھوڑا فائدہ ہے — پھر — ہماری طرف — ان کا لوٹ — آنا ہے — پھر — ہم — ان — کو — شدید عذاب — چکھائیں گے — اس وجہ سے کہ — وہ کفر کرتے تھے",
"""۱۔ دنیا کا فائدہ — محدود؛ آخرت کا عذاب — شدید۔
۲۔ ’’مَتَاعٌ فِي الدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ الْعَذَابَ الشَّدِيدَ بِمَا كَانُوا يَكْفُرُونَ‘‘ — دنیا میں — تھوڑا فائدہ ہے — پھر — ہماری طرف — ان کا لوٹ — آنا ہے — پھر — ہم — ان — کو — شدید عذاب — چکھائیں گے — اس وجہ سے کہ — وہ کفر کرتے تھے — یعنی دنیا کا فائدہ — تھوڑا ہے؛ آخرت میں — شدید عذاب — کفر کی وجہ سے۔
۳۔ عملی سبق: دنیا — عارضی؛ آخرت — حقیقی انجام۔"""
),
}
